questions.explanation:
预处理 a、b 两数之和放入哈希集合（n ≤ 100，最多 1e4 个值），对每次查询 xᵢ，枚举 cₖ 判断 xᵢ - cₖ 是否在集合中即可，总复杂度 O(n² + q·n)。参考程序：

```cpp
#include <iostream>
#include <set>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n;
    int a[105], b[105], c[105];
    set<long long> ab;
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    for (int i = 0; i < n; i++) cin >> c[i];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            ab.insert((long long)a[i] + b[j]);
    int q; cin >> q;
    while (q--) {
        long long x; cin >> x;
        bool ok = false;
        for (int i = 0; i < n; i++) {
            if (ab.count(x - (long long)c[i])) { ok = true; break; }
        }
        cout << (ok ? "Yes" : "No") << "\n";
    }
    return 0;
}
```

设总爆炸次数为 m，怪兽 i 当中心的次数为 kᵢ，则对它造成的总伤害为 a·kᵢ + b·(m-kᵢ) = b·m + (a-b)·kᵢ ≥ hᵢ，故 kᵢ ≥ max(0, ⌈(hᵢ - b·m)/(a-b)⌉)。所有 kᵢ 之和必须等于 m，因此只需 Σkᵢ ≤ m 即存在可行方案。对 m 二分查找最小值即可。参考程序：

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

typedef long long ll;
ll h[100005];
int n; ll A, B;

bool check(ll m) {
    ll need = 0;
    for (int i = 0; i < n; i++) {
        ll rem = h[i] - B * m;
        if (rem > 0) {
            ll k = (rem + (A - B) - 1) / (A - B); // ceil(rem/(A-B))
            need += k;
            if (need > m) return false;
        }
    }
    return need <= m;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n >> A >> B;
    for (int i = 0; i < n; i++) cin >> h[i];
    ll lo = 0, hi = 2000000000LL, ans = hi;
    while (lo <= hi) {
        ll mid = (lo + hi) / 2;
        if (check(mid)) { ans = mid; hi = mid - 1; }
        else lo = mid + 1;
    }
    cout << ans << "\n";
    return 0;
}
```
